struct ApiDoc;

/// A problem details response with this description, for [`problem_responses!`].
pub(crate) fn problem_response(description: &str) -> RefOr<Response> {
    problem_builder(description).build().into()
}

fn problem_builder(description: &str) -> ResponseBuilder {
    ResponseBuilder::new().description(description).content(
        PROBLEM_JSON,
        ContentBuilder::new()
            .schema(Some(Ref::from_schema_name("Problem")))
            .build(),
    )
}

// BadRequest's description repeats pagination::MAX_LIMIT, since it is a literal; a test in
// tests/http.rs checks the two agree.

/// Declares a problem response: its component name is the type's name. Each type must also be
/// listed in `components(responses(..))` of [`ApiDoc`], or its reference dangles.
macro_rules! problem_responses {
    ($($name:ident => $description:literal,)+) => {$(
        #[doc = $description]
        pub struct $name;

        impl<'r> utoipa::ToResponse<'r> for $name {
            fn response() -> (
                &'r str,
                utoipa::openapi::RefOr<utoipa::openapi::Response>,
            ) {
                (stringify!($name), $crate::openapi::problem_response($description))
            }
        }
    )+};
}
pub(crate) use problem_responses;

problem_responses! {
    BadRequest => "`request.malformed`: the body, a path parameter or a query parameter does not parse or does not match the schema, or `limit` is outside 1 to 200. `pagination.invalid_cursor`: the cursor does not decode.",
    RouteNotFound => "`request.not_found`: no API operation has this path.",
    MethodNotAllowed => "`request.method_not_allowed`: the path does not take this method; `Allow` lists the methods it takes.",
    PayloadTooLarge => "`request.too_large`: the body is larger than the server accepts.",
    UnsupportedMediaType => "`request.unsupported_media_type`: the body is not JSON.",
    UnprocessableEntity => "`request.invalid`: the body parses but breaks a rule; `errors` lists each one.",
    InternalError => "`internal.error`: the server failed; the cause is in its log.",
    CsrfRefused => "`auth.csrf_refused`: an unsafe request without a bearer credential did not come from this site: `Sec-Fetch-Site` is not `same-origin`, `Origin` is sent but is not an allowed origin, or neither header is sent.",
    OrganizationNotFound => "`org.not_found`: the request's organization cannot be determined.",
    NoOrganization => "`org.none`: the instance has no organization yet.",
    Unauthenticated => "`auth.unauthenticated`: no credential, or one that names no session of the organization, or an `Authorization` header that is not one `Bearer <credential>`. `auth.session_expired`: the session passed its idle or absolute expiry. `auth.api_key_invalid`: the API key is malformed, fails its checksum, or names no service account of the organization. `auth.access_token_invalid`: the bearer credential is not an app access token this server issued for the organization, or its sign-in was revoked. `auth.access_token_expired`: the app access token is past its 15 minutes; refresh it. `auth.suspended`: the user, or the API key's owner, is suspended.",
    PermissionDenied => "`permission.denied`: the caller does not hold the operation's permission at a scope containing its target.",
}

/// 429 `auth.rate_limited`, with `Retry-After`. A sign-in or token route that takes
/// `rate_limit::RateLimited` lists `(status = 429, response = crate::openapi::RateLimited)`.
pub struct RateLimited;

impl<'r> ToResponse<'r> for RateLimited {
    fn response() -> (&'r str, RefOr<Response>) {
        let retry_after = HeaderBuilder::new()
            .schema(ObjectBuilder::new().schema_type(Type::Integer))
            .description(Some("Seconds to wait before trying again, at least 1."))
            .build();
        let response = problem_builder(
            "`auth.rate_limited`: too many sign-in or token requests from this client address, or \
             too many failed password or TOTP checks for this account; `Retry-After` gives the \
             seconds until the limit's window closes.",
        )
        .header("Retry-After", retry_after)
        .build();
        ("RateLimited", response.into())
    }
}

/// The API's OpenAPI document.
pub fn document() -> utoipa::openapi::OpenApi {
    ApiDoc::openapi()
}

/// The document as the pretty-printed JSON committed in `openapi/stepclimb.json`.
pub fn document_json() -> String {
    let mut json = document()
        .to_pretty_json()
        .expect("the generated document serializes");
    json.push('\n');
    json
}
